1	package auth
2	
3	import (
4		"fmt"
5	
6		"github.com/entireio/auth-go/tokens"
7		"github.com/entireio/cli/internal/entireclient/contexts"
8		"github.com/entireio/cli/internal/entireclient/tokenstore"
9	)
10	
11	// CurrentContextToken returns the login JWT for the active context in
12	// contexts.json, or ("", false) when there is no current context or it
13	// has no stored token. This is the contexts.json half of the CLI's
14	// credential resolution; callers fall back to the legacy keyring entry so
15	// pre-contexts logins keep working until migrated.
16	func CurrentContextToken() (string, bool) {
17		f, err := contexts.Load(contexts.DefaultConfigDir())
18		if err != nil {
19			return "", false
20		}
21		c := f.Find(f.CurrentContext)
22		if c == nil {
23			return "", false
24		}
25		tok, err := LoginTokenForContext(c)
26		if err != nil || tok == "" {
27			return "", false
28		}
29		return tok, true
30	}
31	
32	// RemoveCurrentContext deletes the active context from contexts.json and
33	// its keyring token, advancing current_context to whatever remains. It is
34	// a no-op (returns nil) when there is no current context. Used by logout.
35	func RemoveCurrentContext() error {
36		// Read-modify-write in a single locked Modify so the context we delete
37		// is exactly the one we capture the keychain slot from (separate Load +
38		// Modify would race a concurrent `auth use`).
39		var svc, handle string
40		if err := contexts.Modify(contexts.DefaultConfigDir(), func(f *contexts.File) (bool, error) {
41			current := f.Find(f.CurrentContext)
42			if current == nil {
43				return false, nil
44			}
45			svc, handle = current.KeychainService, current.Handle
46			f.Delete(current.Name)
47			// Delete advances current_context to a surviving context; for logout
48			// that would silently re-authenticate as another account. Leave no
49			// active context — logged out means logged out.
50			f.CurrentContext = ""
51			return true, nil
52		}); err != nil {
53			return fmt.Errorf("remove current context: %w", err)
54		}
55		// Best-effort keychain cleanup, sequenced off the context just removed.
56		// A missing entry is fine — the contexts.json removal above is what makes
57		// us "logged out".
58		if svc != "" && handle != "" {
59			_ = tokenstore.Delete(svc, handle) //nolint:errcheck // best-effort; contexts.json removal is the source of truth for logout
60		}
61		return nil
62	}
63	
64	// RemoveAllContexts deletes every stored context, its keyring token, and all
65	// cluster bindings — a full local logout. Returns the number of contexts
66	// removed. Best-effort on the keyring deletes; the contexts.json clear is
67	// what makes the CLI fully logged out (no surviving binding can authenticate
68	// a clone afterward).
69	func RemoveAllContexts() (int, error) {
70		var removed int
71		if err := contexts.Modify(contexts.DefaultConfigDir(), func(f *contexts.File) (bool, error) {
72			if len(f.Contexts) == 0 && f.CurrentContext == "" && len(f.ClusterContexts) == 0 {
73				return false, nil
74			}
75			for _, c := range f.Contexts {
76				if c.KeychainService != "" && c.Handle != "" {
77					_ = tokenstore.Delete(c.KeychainService, c.Handle) //nolint:errcheck // best-effort; the contexts.json clear below is authoritative
78				}
79				removed++
80			}
81			f.Contexts = nil
82			f.CurrentContext = ""
83			f.ClusterContexts = nil
84			return true, nil
85		}); err != nil {
86			return 0, fmt.Errorf("remove all contexts: %w", err)
87		}
88		return removed, nil
89	}
90	
91	// SetCurrentContext makes name the active context. Returns an error when
92	// no context with that name exists (a stale current pointer is a foot-gun).
93	func SetCurrentContext(name string) error {
94		if err := contexts.Modify(contexts.DefaultConfigDir(), func(f *contexts.File) (bool, error) {
95			if f.Find(name) == nil {
96				return false, fmt.Errorf("no login context named %q (run `entire auth contexts` to list)", name)
97			}
98			if f.CurrentContext == name {
99				return false, nil
100			}
101			f.CurrentContext = name
102			return true, nil
103		}); err != nil {
104			return fmt.Errorf("set current context: %w", err)
105		}
106		return nil
107	}
108	
109	// Contexts returns all stored login contexts and the current context name,
110	// for listing/switching. Order matches on-disk order.
111	func Contexts() ([]*contexts.Context, string, error) {
112		f, err := contexts.Load(contexts.DefaultConfigDir())
113		if err != nil {
114			return nil, "", fmt.Errorf("load contexts: %w", err)
115		}
116		return f.Contexts, f.CurrentContext, nil
117	}
118	
119	// ContextStore wraps the legacy keyring Store so token *reads* prefer the
120	// active contexts.json context, falling back to the legacy
121	// entire-cli/<authBaseURL> entry. Writes are inherited from Store
122	// unchanged — login dual-writes the context via RecordLoginContext, so the
123	// write side needs no override here.
124	//
125	// This is the single seam that lets the control-plane readers (the
126	// tokenmanager, LookupCurrentToken, and `auth status`/`list`) honor a
127	// contexts.json login — including one created by entiredb's CLIs that
128	// share this file. *ContextStore satisfies both the cli package's
129	// tokenStore interface and auth-go's tokenstore.Store.
130	type ContextStore struct {
131		*Store
132	}
133	
134	// NewContextStore returns a context-preferring view over the legacy store.
135	func NewContextStore() *ContextStore {
136		return &ContextStore{Store: NewStore()}
137	}
138	
139	// GetToken prefers the active context's token, falling back to the legacy
140	// entry keyed by baseURL.
141	func (s *ContextStore) GetToken(baseURL string) (string, error) {
142		if tok, ok := CurrentContextToken(); ok {
143			return tok, nil
144		}
145		return s.Store.GetToken(baseURL)
146	}
147	
148	// LoadTokens (the tokenstore.Store method the tokenmanager calls) prefers
149	// the active context's token, falling back to the legacy profile entry.
150	func (s *ContextStore) LoadTokens(profile string) (tokens.TokenSet, error) {
151		if tok, ok := CurrentContextToken(); ok {
152			return tokens.TokenSet{AccessToken: tok}, nil
153		}
154		return s.Store.LoadTokens(profile)
155	}
