1	package discovery
2	
3	import (
4		"slices"
5		"testing"
6	)
7	
8	func TestParseReplicas(t *testing.T) {
9		tests := []struct {
10			name   string
11			header string
12			want   []string
13		}{
14			{"empty", "", nil},
