	var existed bool
	if err := contexts.Modify(contexts.DefaultConfigDir(), func(f *contexts.File) (bool, error) {
		if _, ok := f.ClusterContexts[host]; !ok {
			return false, nil
		}
		delete(f.ClusterContexts, host)
		existed = true
		return true, nil
	}); err != nil {
		return false, fmt.Errorf("unbind cluster: %w", err)
	}
